def compute_wins(upper_bound, t1, t2):
    # Grundy numbers g[k] for k up to upper_bound
    g = [0] * (upper_bound + 1)
    # g[0] = g[1] = 0 already
    def xor_for_split(k, t):
        a = k // t
        s = k % t
        x = 0
        if ((t - s) % 2) == 1:
            x ^= g[a]
        if (s % 2) == 1:
            # a+1 <= k for t >= 2; safe since we fill in increasing k
            x ^= g[a + 1]
        return x
    def mex(values):
        seen = set(values)
        m = 0
        while m in seen:
            m += 1
        return m
